 public sealed partial class MobileGameApp {
  void WorldInvestment(string kind,int x,int y,int property=0){var q=empire.QuoteCityInvestment(kind,x,y,property);var d=empireConfig.City.Business(kind);var m=Studio.Modal(root,(property==0?"BUILD ":"UPGRADE ")+WorldLabel(kind),PermanentCityScreen);Studio.Image(m,d.Art??kind,250,180,220,220);Studio.Label(m,CityRole(d)+"\nOne project takes "+EmpireDuration(q.Seconds)+". Cash cost includes its labor and permit.",44,420,632,140,27,Studio.Text,TextAlignmentOptions.Center);Studio.Label(m,"NEXT DAY NET FORECAST\n"+CityMoney(q.BeforeNet)+" → "+CityMoney(q.AfterNet)+"\nBased on current residents,prices and running costs.",44,595,632,155,29,Studio.Accent,TextAlignmentOptions.Center,true);for(int i=0;i<q.Costs.Length;i++){var item=q.Costs[i];long owned=q.Owned.Single(o=>o.ItemId==item.ItemId).Quantity;Studio.Label(m,ItemName(item.ItemId)+"   "+owned+" / "+item.Quantity,44,790+i*55,632,50,27,owned>=item.Quantity?Studio.Text:FlatUI.Hex("#FFD078"));}
   var missing=q.Costs.FirstOrDefault(c=>q.Owned.Single(o=>o.ItemId==c.ItemId).Quantity<c.Quantity);string action=!q.Unlocked?"DEVELOP MY CITY FIRST":!q.BuilderAvailable?"VIEW MY BUILDER":missing!=null?"FIND "+ItemName(missing.ItemId):property==0?"START CONSTRUCTION":"START UPGRADE";
   Studio.Button(m,action,44,1100,632,125,()=>{if(!q.Unlocked){PermanentCityScreen();return;}if(!q.BuilderAvailable){WorldPropertyDetails(empire.Snapshot.City.Jobs[0].PropertyId);return;}if(missing!=null){WorldMaterial(missing.ItemId,(int)(missing.Quantity-q.Owned.Single(o=>o.ItemId==missing.ItemId).Quantity),()=>WorldInvestment(kind,x,y,property));return;}WorldAction(()=>{if(property==0)empire.BuildCity(Guid.NewGuid().ToString("N"),kind,x,y,EmpireNow);else empire.UpgradeCity(Guid.NewGuid().ToString("N"),property,EmpireNow);});},true);}
  void WorldMaterial(string item,int needed,Action back){var m=Studio.Modal(root,"FIND "+ItemName(item),back);if(item=="CASH"){Studio.Image(m,"cafe",250,200,220,220);Studio.Label(m,"Your operating city earns saved cash at closing. Inspect net margins,improve a useful business,reduce unnecessary costs or pause an unprofitable operation.\n\nFinancing is optional after day4. It brings cash forward and creates a disclosed repayment obligation.\n\nNo resource is awarded just by opening this panel.",44,500,632,450,29,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,empire.Snapshot.City.Day>=4?"COMPARE FINANCING":"RETURN TO MY OPERATING CITY",44,1100,632,125,()=>{if(empire.Snapshot.City.Day>=4)WorldFinance(back);else PermanentCityScreen();},true);return;}var good=empireConfig.City.Good(item);int amount=Math.Min(20,Math.Max(1,needed));string source=item=="WOOD"?"Owned farms produce timber each operating day; a developed construction company can supply more.":item=="STEEL"?"An owned construction company can produce steel. Materials also have a published cash market.":"Owned producers can supply this item. Inspect their production and operating cost.";Studio.Image(m,item=="WOOD"?"farm":"factory",250,200,220,220);Studio.Label(m,source+"\n\nMarket: "+CityMoney(good.ImportPrice)+" per unit\nNeed "+needed+" · buy "+amount+" for "+CityMoney(amount*good.ImportPrice)+"\nOwned cash: "+CityMoney(empire.Snapshot.Economy.Amount("CASH"))+"\n\nThe order returns to your exact project.",44,500,632,470,29,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,"BUY "+amount+" · "+CityMoney(amount*good.ImportPrice),44,1100,632,125,()=>WorldAction(()=>empire.BuyCityMaterials(Guid.NewGuid().ToString("N"),item,amount,EmpireNow),back),true);}
  void WorldFinance(Action back=null){back=back??WorldDesk;var city=empire.Snapshot.City;var m=Studio.Modal(root,"CITY FINANCING",back);var loan=city.Loans.FirstOrDefault(l=>l.Remaining>0);if(loan!=null){Studio.Image(m,"bank",250,200,220,220);Studio.Label(m,"REMAINING "+CityMoney(loan.Remaining)+"\nScheduled installment "+CityMoney(loan.Installment)+" per operating day\nArrears "+CityMoney(loan.Arrears)+"\n\nTotal originally due "+CityMoney(loan.Principal+loan.Fee)+". The fixed fee does not compound.\n\nRepay early with earned cash. Unpaid amounts remain owed until repaid.",44,480,632,460,30,Studio.Text,TextAlignmentOptions.Center);long amount=Math.Min(loan.Remaining,50);Studio.Button(m,"REPAY "+CityMoney(amount),44,1100,632,125,()=>WorldAction(()=>empire.RepayCityLoan(Guid.NewGuid().ToString("N"),loan.Id,amount,EmpireNow),()=>WorldFinance(back)),true);return;}Studio.Label(m,"Borrowing is optional. More cash now creates a future financing outflow. Operating bills still apply.\n\nTerms unlock after day4. Earn cash by operating the city instead if you prefer.",44,235,632,230,29,Studio.Text,TextAlignmentOptions.Center);long[] amounts={100,300,600};for(int i=0;i<amounts.Length;i++){long principal=amounts[i],total=principal+principal/10,installment=(total+9)/10;float y=520+i*180;Studio.Label(m,"Receive "+CityMoney(principal)+" · repay "+CityMoney(total)+" total\n10 days · up to "+CityMoney(installment)+" / day",44,y,632,80,27,Studio.Text,TextAlignmentOptions.Center);var b=Studio.Button(m,"REVIEW "+CityMoney(principal)+" TERMS",44,y+85,632,75,()=>WorldLoanTerms(principal,back));b.interactable=city.Day>=4&&(principal<600||city.Population(empireConfig.City)>=72);}}
  void WorldLoanTerms(long principal,Action back){long fee=principal/10,total=principal+fee;var r=empire.ForecastCity();var m=Studio.Modal(root,"BORROWING HAS A COST",()=>WorldFinance(back));Studio.Image(m,"bank",250,200,220,220);Studio.Label(m,"Cash received   "+CityMoney(principal)+"\nFixed financing fee   "+CityMoney(fee)+"\nTotal repayment   "+CityMoney(total)+"\n10 operating days · up to "+CityMoney((total+9)/10)+" per day\n\nCurrent next-day operating margin "+CityMoney(r.OperatingNet)+"\nRepayments begin the following operating day. Missed amounts remain owed; they do not buy more progress.\n\nCompare the investment’s additional margin with its daily repayment before borrowing.",44,480,632,540,28,Studio.Text,TextAlignmentOptions.Center);Studio.Button(m,"ACCEPT FIXED TERMS",44,1100,632,125,()=>WorldAction(()=>empire.FinanceCity(Guid.NewGuid().ToString("N"),principal,EmpireNow),back),true);}
  void WorldEmployees(int id){var p=empire.Snapshot.City.Properties.Single(b=>b.Id==id);var d=empireConfig.City.Business(p.Kind);int staff=CityWorkforce.Staff(d,p);var m=Studio.Modal(root,WorldLabel(p.Kind)+" EMPLOYEES",()=>WorldPropertyDetails(id));Studio.Image(m,d.Art??p.Kind,250,200,220,220);Studio.Label(m,staff+" / "+d.MaxStaff+" EMPLOYEES\nWage "+CityMoney(d.DailyWage)+" per employee per operating day\nHiring fee "+CityMoney(20)+" per new employee\n\nStaff increases capacity and production within the business’s limits. Extra capacity cannot create more residents or guarantee purchases.\n\nYour residential population limits available workers. Pausing an operation avoids active wages,but its property still has a small bill.",44,480,632,480,29,Studio.Text,TextAlignmentOptions.Center);var minus=Studio.Button(m,"ONE FEWER",44,1090,300,110,()=>WorldAction(()=>empire.StaffCityBusiness(Guid.NewGuid().ToString("N"),id,staff-1,EmpireNow),()=>WorldEmployees(id)));minus.interactable=staff>0;var plus=Studio.Button(m,"HIRE ONE · $20",360,1090,316,110,()=>WorldAction(()=>empire.StaffCityBusiness(Guid.NewGuid().ToString("N"),id,staff+1,EmpireNow),()=>WorldEmployees(id)),true);plus.interactable=staff<d.MaxStaff;}
  void WorldAdvertising(int id){var p=empire.Snapshot.City.Properties.Single(b=>b.Id==id);var r=empire.ForecastCity().Businesses.First(b=>b.PropertyId==id);var m=Studio.Modal(root,"CUSTOMERS & ADVERTISING",()=>WorldPropertyDetails(id));Studio.Label(m,"NEXT DAY FUNNEL\n"+r.PotentialCustomers+" eligible needs considered\n"+r.Customers+" expected purchases\nNet "+CityMoney(r.Net)+" after this business’s costs\n\nAdvertising competes for a share of existing demand. Price,walking distance,stock and staff still matter. Unserved customers create no sales. A campaign costs money even if it fails to improve margin.",44,245,632,470,30,Studio.Text,TextAlignmentOptions.Center);int[] budgets={0,5,15};string[] labels={"NO CAMPAIGN","LOCAL FLYERS · $5 / DAY","REGIONAL ADS · $15 / DAY"};for(int i=0;i<3;i++){int budget=budgets[i];var b=Studio.Button(m,labels[i],44,785+i*130,632,100,()=>WorldAction(()=>empire.MarketCityBusiness(Guid.NewGuid().ToString("N"),id,budget,EmpireNow),()=>WorldAdvertising(id)),p.MarketingBudget==budget);b.interactable=empire.Snapshot.City.Day>=3;}}
  void WorldAgreements(){var city=empire.Snapshot.City;var m=Studio.Modal(root,"SUPPLIERS & SPONSORS",WorldStrategy);Studio.Label(m,"LOCAL ROASTER · 3 OPERATING DAYS\n$5 per day; imported beans cost $1 instead of $2. Useful only if the savings justify the fee.\n\nCOFFEE FAIR · 3 OPERATING DAYS\n$8 daily campaign obligation. Pays $20 for a day with at least5 actual coffee purchases. Below that target it pays nothing.\n\nThese are fictional in-game agreements. Both run on actual trading days and appear in your cashflow forecast.",44,245,632,560,30,Studio.Text,TextAlignmentOptions.Center);var supplier=Studio.Button(m,city.PartnerEndsDay>=city.Day?"SUPPLIER AGREEMENT ACTIVE":"SIGN SUPPLIER AGREEMENT",44,900,632,100,()=>WorldAction(()=>empire.AgreeCityPartner(Guid.NewGuid().ToString("N"),false,EmpireNow),WorldAgreements),true);supplier.interactable=city.Day>=5&&city.PartnerEndsDay<city.Day;var sponsor=Studio.Button(m,city.SponsorEndsDay>=city.Day?"SPONSORSHIP ACTIVE":"SIGN COFFEE FAIR TERMS",44,1050,632,100,()=>WorldAction(()=>empire.AgreeCityPartner(Guid.NewGuid().ToString("N"),true,EmpireNow),WorldAgreements));sponsor.interactable=city.Day>=7&&city.SponsorEndsDay<city.Day;}
 }
